        "https://dpi.gov.gy/wp-content/uploads/2016/06/Gazetteer-PLACE-NAMES-ALONG-GUYANA%E2%80%99S-ROADS.pdf",
        "https://en.wikipedia.org/wiki/Adventure,_Guyana",
        "https://www.geonames.org/3376880",
        "https://guyanachronicle.com/2023/08/13/philadelphia",
        "https://en.wikipedia.org/wiki/Pomeroon_River",
